// Sunset Vice — small random helpers. Everything in the game that needs
// luck goes through one seeded generator so a run can be replayed.
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function range(rand, lo, hi) {
  return lo + rand() * (hi - lo);
}

export function rangeInt(rand, lo, hi) {
  return Math.floor(range(rand, lo, hi + 1));
}

export function pick(rand, list) {
  return list[Math.floor(rand() * list.length)];
}

export function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

export function dist2(ax, ay, bx, by) {
  const dx = bx - ax;
  const dy = by - ay;
  return dx * dx + dy * dy;
}

// Shortest signed turn from angle a toward angle b, in (-PI, PI].
export function angleLerp(a, b, t) {
  let d = b - a;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d <= -Math.PI) d += Math.PI * 2;
  return a + d * t;
}
